const baseUrl = env.get('HA_BASE_URL') || 'http://homeassistant.local:8123';
const token  = env.get('HA_TOKEN');

if (!token) {
    node.error('HA_TOKEN Umgebungsvariable nicht gesetzt!');
    return null;
}

msg.url     = baseUrl + '/api/config/config_entries';
msg.method  = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + token };

msg._haBaseUrl = baseUrl;
msg._haToken   = token;
msg._acPayload = msg.payload;

return msg;

const entries = msg.payload;

if (!Array.isArray(entries)) {
    node.error('HA API Fehler: ' + JSON.stringify(entries));
    return null;
}

const greeEntries = entries.filter(e => e.domain === 'gree');

if (greeEntries.length === 0) {
    node.warn('Keine Gree-Config-Einträge in HA gefunden');
    return null;
}

node.status({ fill:'blue', shape:'dot', text: greeEntries.length + ' Eintrag/Einträge' });

// Einen msg pro Entry senden
return [ greeEntries.map(entry => ({
    ...msg,
    payload:    null,
    url:        msg._haBaseUrl + '/api/config/config_entries/entry/' + entry.entry_id + '/reload',
    method:     'POST',
    headers:    { 'Authorization': 'Bearer ' + msg._haToken, 'Content-Type': 'application/json' },
    _entryId:   entry.entry_id,
    _entryTitle: entry.title || entry.entry_id
})) ];

const ok = msg.statusCode >= 200 && msg.statusCode < 300;
const label = msg._entryTitle || msg._entryId || '?';

if (ok) {
    node.log('✅ Gree Eintrag neugeladen: ' + label);
    node.status({ fill:'green', shape:'dot', text: label + ' OK' });
} else {
    node.error('❌ Reload fehlgeschlagen [' + msg.statusCode + ']: ' + label);
    node.status({ fill:'red', shape:'ring', text: label + ' ' + msg.statusCode });
}

msg.payload = { entry: label, status: msg.statusCode, ok };
return msg;
